export const statuses=['미개봉','사용 중','사용 완료','폐기'];
export const categories=['스킨케어','메이크업','선케어','클렌징','헤어·바디','향수','기타'];
export function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;let d=new Date(s+'T00:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s&&+s.slice(0,4)>=1900;}
export function addMonths(s,m){if(!validDate(s)||!Number.isInteger(+m)||+m<1||+m>120)return null;const [y,mo,d]=s.split('-').map(Number);const last=new Date(Date.UTC(y,mo-1+(+m)+1,0)).getUTCDate();return new Date(Date.UTC(y,mo-1+(+m),Math.min(d,last))).toISOString().slice(0,10);}
export function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function deadline(p,now=today()){let list=[];if(validDate(p.expiry))list.push({date:p.expiry,reason:'표시된 사용기한'});if(p.status!=='미개봉'&&validDate(p.opened)&&p.months){const date=addMonths(p.opened,p.months);if(date)list.push({date,reason:`개봉일 ${p.opened} + ${p.months}개월`});}list.sort((a,b)=>a.date.localeCompare(b.date));if(!list.length)return {date:null,days:null,label:'날짜 확인 필요',reason:'표시된 사용기한 또는 개봉일과 개봉 후 사용기간을 입력하세요.'};const first=list[0],days=Math.round((new Date(first.date+'T00:00:00Z')-new Date(now+'T00:00:00Z'))/86400000);return {...first,days,label:days<0?'기한 경과':days<=30?'30일 이내':'여유 있어요',reason:list.map(x=>`${x.reason} → ${x.date}`).join(' / ')+(list.length>1?' · 빠른 날짜 적용':'')};}
export function candidates(text){return [...text.matchAll(/(?:19|20)\d{2}[.\-/년\s]+\d{1,2}[.\-/월\s]+\d{1,2}일?/g)].map(m=>{const a=m[0].match(/\d+/g),date=`${a[0]}-${a[1].padStart(2,'0')}-${a[2].padStart(2,'0')}`,context=text.slice(Math.max(0,m.index-25),m.index+m[0].length+20).replace(/\n/g,' '),before=text.slice(Math.max(0,m.index-30),m.index).split(/\n/).pop(),markers=[...before.matchAll(/제조|MFG|MFD|생산|EXP|사용기한|소비기한|유통기한/gi)],manufacture=/제조|MFG|MFD|생산/i.test(markers.at(-1)?.[0]||''),explicit=/까지|사용기한|유통기한|EXP|소비기한/i.test(context);return {date,context,manufacture,explicit};}).filter(x=>validDate(x.date));}
export function validateProduct(p){if(!p||typeof p!=='object'||typeof p.id!=='string'||!p.id||typeof p.name!=='string'||!p.name.trim()||p.name.length>120||!statuses.includes(p.status)||!categories.includes(p.category))throw Error('제품 형식이 올바르지 않습니다.');for(const k of ['expiry','opened'])if(p[k]&&!validDate(p[k]))throw Error('올바르지 않은 날짜입니다.');if(p.months&&(!Number.isInteger(+p.months)||+p.months<1||+p.months>120))throw Error('사용기간은 1~120개월이어야 합니다.');for(const k of ['brand','memo'])if(typeof p[k]!=='string'||p[k].length>10000)throw Error('텍스트 형식을 확인하세요.');if(typeof p.photo!=='string'||(p.photo&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.photo))||p.photo.length>12000000)throw Error('지원하지 않는 사진입니다.');return p;}
